policy_content.body:
@id("viewAndCreate-token")
permit(principal, action in [TaskApp::Action::"ViewTask", TaskApp::Action::"CreateTask"], resource) when {
  context has tokens && (
    context.tokens has localmockidp_userinfo_token ||
    context.tokens has localmockidp_id_token
  )
};

@id("ownerModify-token")
permit(principal, action in [TaskApp::Action::"UpdateTask", TaskApp::Action::"DeleteTask"], resource) when {
  context has tokens && (
    (context.tokens has localmockidp_userinfo_token && context.tokens.localmockidp_userinfo_token.hasTag("sub") && context.tokens.localmockidp_userinfo_token.getTag("sub").contains(resource.owner)) ||
    (context.tokens has localmockidp_id_token && context.tokens.localmockidp_id_token.hasTag("sub") && context.tokens.localmockidp_id_token.getTag("sub").contains(resource.owner))
  )
};

@id("ownerModify-user")
permit(principal is TaskApp::User, action in [TaskApp::Action::"UpdateTask", TaskApp::Action::"DeleteTask"], resource) when {
  context has userId && resource.owner == context.userId
};

schema.body:
namespace Jans {
  type Url = {
    host: String,
    path: String,
    protocol: String
  };
}

namespace LocalMockIdP {
  entity TrustedIssuer = {
    issuer_entity_id: Jans::Url
  };

  entity id_token = {
    token_type?: String,
    jti?: String,
    iss?: TrustedIssuer,
    exp?: Long,
    validated_at?: Long
  } tags Set<String>;

  entity Access_token = {
    token_type?: String,
    jti?: String,
    iss?: TrustedIssuer,
    exp?: Long,
    validated_at?: Long
  } tags Set<String>;

  entity Userinfo_token = {
    token_type?: String,
    jti?: String,
    iss?: TrustedIssuer,
    exp?: Long,
    validated_at?: Long
  } tags Set<String>;
}

namespace TaskApp {
  entity User;
  entity Task {
    owner: String,
    title: String,
    completed: Bool
  };

  entity Any;

  action "CreateTask" appliesTo {
    principal: [User, Any],
    resource: [Task],
    context: {
      userId?: String,
      tokens?: TokensContext
    }
  };

  action "ViewTask" appliesTo {
    principal: [User, Any],
    resource: [Task],
    context: {
      userId?: String,
      tokens?: TokensContext
    }
  };

  action "UpdateTask" appliesTo {
    principal: [User, Any],
    resource: [Task],
    context: {
      userId?: String,
      tokens?: TokensContext
    }
  };

  action "DeleteTask" appliesTo {
    principal: [User, Any],
    resource: [Task],
    context: {
      userId?: String,
      tokens?: TokensContext
    }
  };

  type TokensContext = {
    total_token_count: Long,
    localmockidp_userinfo_token?: LocalMockIdP::Userinfo_token,
    localmockidp_id_token?: LocalMockIdP::id_token
  };
}
